import{_ as t,c as d,a as v,o as s}from"./index-ChxTSPjq.js";const f={class:"standard-container"},b={__name:"Standard",setup(i){return(r,a)=>(s(),d("div",f,[...a[0]||(a[0]=[v('<div class="page-header" data-v-6af299b3><h2 data-v-6af299b3>RECIST 1.1 评估标准</h2><p class="header-subtitle" data-v-6af299b3>实体瘤疗效评价标准（Response Evaluation Criteria in Solid Tumors）第 1.1 版</p></div><div class="standard-content" data-v-6af299b3><div class="section target-section" data-v-6af299b3><h3 class="section-title" data-v-6af299b3>6.1 靶病灶判定</h3><div class="standard-table" data-v-6af299b3><table data-v-6af299b3><thead data-v-6af299b3><tr data-v-6af299b3><th data-v-6af299b3>类别</th><th data-v-6af299b3>判定标准</th></tr></thead><tbody data-v-6af299b3><tr data-v-6af299b3><td data-v-6af299b3><span class="badge cr" data-v-6af299b3>CR 完全缓解</span></td><td data-v-6af299b3>所有靶病灶消失；所有病理淋巴结短轴 &lt; 10 mm</td></tr><tr data-v-6af299b3><td data-v-6af299b3><span class="badge pr" data-v-6af299b3>PR 部分缓解</span></td><td data-v-6af299b3>靶病灶 SLD 较基线下降 ≥30%</td></tr><tr data-v-6af299b3><td data-v-6af299b3><span class="badge sd" data-v-6af299b3>SD 疾病稳定</span></td><td data-v-6af299b3>既达不到 PR（缩小不足），也未达 PD（增大不足），介于两者之间</td></tr><tr data-v-6af299b3><td data-v-6af299b3><span class="badge pd" data-v-6af299b3>PD 疾病进展</span></td><td data-v-6af299b3> 满足以下任一：<br data-v-6af299b3> ① SLD 较研究期间最小值（nadir，含基线）增加 <strong data-v-6af299b3>≥20%</strong> 且绝对值增加 <strong data-v-6af299b3>≥5 mm</strong>；<br data-v-6af299b3> ② 出现新病灶 </td></tr></tbody></table></div><div class="formula-box" data-v-6af299b3><div class="formula-line" data-v-6af299b3><code data-v-6af299b3>SLD_baseline = Σ 各靶病灶最长径（基线）</code></div><div class="formula-line" data-v-6af299b3><code data-v-6af299b3>SLD_nadir = min(SLD_baseline, SLD_followup_1, SLD_followup_2, …)</code></div><div class="formula-line" data-v-6af299b3><code data-v-6af299b3>PR：(SLD_baseline − SLD_now) / SLD_baseline ≥ 0.30</code></div><div class="formula-line" data-v-6af299b3><code data-v-6af299b3>PD：(SLD_now − SLD_nadir) / SLD_nadir ≥ 0.20 AND (SLD_now − SLD_nadir) ≥ 5 mm → 或 出现新病灶</code></div></div><div class="warning-box" data-v-6af299b3><h4 data-v-6af299b3>⚠️ 三个极易出错的细节</h4><ol data-v-6af299b3><li data-v-6af299b3><strong data-v-6af299b3>PD 参照是 nadir（最低值），不是基线。</strong><br data-v-6af299b3> 例：基线 100 → 最低 50 → 复查 60：相对最低值 +20%（=+60）且绝对 +10mm≥5 → 判 PD。<br data-v-6af299b3> 若回升到 58（+16%&lt;20%）则仍 SD。 </li><li data-v-6af299b3><strong data-v-6af299b3>PD 双条件缺一不可：</strong>既需相对 +20%，又需绝对 +5 mm。<br data-v-6af299b3>小病灶微小波动不应误判为进展。</li><li data-v-6af299b3><strong data-v-6af299b3>新病灶 = PD，</strong>无论大小、无论出现在何处（含 FDG-PET 发现）。</li></ol></div></div><div class="section non-target-section" data-v-6af299b3><h3 class="section-title" data-v-6af299b3>6.2 非靶病灶判定</h3><div class="standard-table" data-v-6af299b3><table data-v-6af299b3><thead data-v-6af299b3><tr data-v-6af299b3><th data-v-6af299b3>类别</th><th data-v-6af299b3>判定标准</th></tr></thead><tbody data-v-6af299b3><tr data-v-6af299b3><td data-v-6af299b3><span class="badge cr" data-v-6af299b3>CR</span></td><td data-v-6af299b3>所有非靶病灶消失；所有淋巴结短轴 &lt; 10 mm</td></tr><tr data-v-6af299b3><td data-v-6af299b3><span class="badge sd" data-v-6af299b3>非CR/非PD (IR/SD)</span></td><td data-v-6af299b3>存在 ≥1 个非靶病灶，或肿瘤标志物持续高于正常</td></tr><tr data-v-6af299b3><td data-v-6af299b3><span class="badge pd" data-v-6af299b3>PD</span></td><td data-v-6af299b3>已有非靶病灶明确进展，或出现任何新病灶</td></tr></tbody></table></div><div class="note-box" data-v-6af299b3><p data-v-6af299b3><strong data-v-6af299b3>非靶 PD 的&quot;明确&quot;二字：</strong>非靶病灶的轻微增大不构成 PD，必须是<strong data-v-6af299b3>明确（unequivocal）进展</strong>（如胸水从少量到大量、淋巴管炎从局限到弥漫）。系统实现时切忌把非靶尺寸小幅变化自动判为 PD。</p></div></div><div class="section confirmation-section" data-v-6af299b3><h3 class="section-title" data-v-6af299b3>6.3 确认规则（Confirmation）</h3><ul class="confirm-list" data-v-6af299b3><li data-v-6af299b3>在<strong data-v-6af299b3>非随机试验</strong>中，<strong data-v-6af299b3>CR 与 PR</strong>须在治疗后 <strong data-v-6af299b3>≥4 周</strong>复查确认。</li><li data-v-6af299b3><strong data-v-6af299b3>随机试验</strong>可由方案决定是否需确认（多数不强制），但确认性的 PR 在后续访视中视为<strong data-v-6af299b3>&quot;持续 PR&quot;</strong>，直至满足 PD 标准——后续判定参照 <strong data-v-6af299b3>nadir 而非基线</strong>。</li><li data-v-6af299b3><strong data-v-6af299b3>PD 一般不需确认</strong>（除非征象模棱两可）。</li></ul></div><div class="section flowchart-section" data-v-6af299b3><h3 class="section-title" data-v-6af299b3>图 1 · 靶病灶疗效判定流程图</h3><div class="flowchart" data-v-6af299b3><div class="fc-node fc-start" data-v-6af299b3>计算 SLD（最长径之和）</div><div class="fc-arrow-down" data-v-6af299b3></div><div class="fc-row" data-v-6af299b3><div class="fc-branch fc-question" data-v-6af299b3>所有靶病灶消失？</div><div class="fc-arrow-right" data-v-6af299b3></div><div class="fc-result fc-cr" data-v-6af299b3>CR（节点 &lt;10mm）</div></div><div class="fc-arrow-down fc-from-left" data-v-6af299b3></div><div class="fc-row" data-v-6af299b3><div class="fc-branch fc-question" data-v-6af299b3>SLD 较基线 ↓≥30%？</div><div class="fc-arrow-right" data-v-6af299b3></div><div class="fc-result fc-pr" data-v-6af299b3>PR</div></div><div class="fc-arrow-down fc-from-left" data-v-6af299b3></div><div class="fc-row" data-v-6af299b3><div class="fc-branch fc-question" data-v-6af299b3>较 nadir ↑≥20% 且 绝对↑≥5mm<br data-v-6af299b3>或新病灶？</div><div class="fc-arrow-right" data-v-6af299b3></div><div class="fc-result fc-pd" data-v-6af299b3>PD</div></div><div class="fc-arrow-down fc-from-left" data-v-6af299b3></div><div class="fc-row" data-v-6af299b3><div class="fc-branch fc-empty" data-v-6af299b3></div><div class="fc-arrow-right" data-v-6af299b3></div><div class="fc-result fc-sd" data-v-6af299b3>SD（介于 PR 与 PD 之间）</div></div><div class="fc-arrow-down" data-v-6af299b3></div><div class="fc-node fc-end" data-v-6af299b3>再与非靶病灶结果合并 → 总体疗效</div></div><p class="flowchart-note" data-v-6af299b3>靶病灶疗效判定依赖 <strong data-v-6af299b3>SLD 与 nadir 的比较</strong>：CR 优先判定，其次依次为 PR、PD，余者为 SD。</p></div><div class="section matrix-section" data-v-6af299b3><h3 class="section-title" data-v-6af299b3>整体评价决策矩阵</h3><div class="standard-table matrix-table" data-v-6af299b3><table data-v-6af299b3><thead data-v-6af299b3><tr data-v-6af299b3><th data-v-6af299b3>Target 靶病灶</th><th data-v-6af299b3>Non-Target 非靶病灶</th><th data-v-6af299b3>New Lesion 新病灶</th><th data-v-6af299b3>Overall 整体疗效</th></tr></thead><tbody data-v-6af299b3><tr data-v-6af299b3><td data-v-6af299b3>CR</td><td data-v-6af299b3>CR</td><td data-v-6af299b3>No</td><td data-v-6af299b3><span class="badge cr" data-v-6af299b3>CR</span></td></tr><tr data-v-6af299b3><td data-v-6af299b3>CR</td><td data-v-6af299b3>Non-CR/Non-PD</td><td data-v-6af299b3>No</td><td data-v-6af299b3><span class="badge pr" data-v-6af299b3>PR</span></td></tr><tr data-v-6af299b3><td data-v-6af299b3>PR</td><td data-v-6af299b3>Non-CR/Non-PD or CR</td><td data-v-6af299b3>No</td><td data-v-6af299b3><span class="badge pr" data-v-6af299b3>PR</span></td></tr><tr data-v-6af299b3><td data-v-6af299b3>SD</td><td data-v-6af299b3>Non-CR/Non-PD or CR</td><td data-v-6af299b3>No</td><td data-v-6af299b3><span class="badge sd" data-v-6af299b3>SD</span></td></tr><tr data-v-6af299b3><td data-v-6af299b3>PD</td><td data-v-6af299b3>Any</td><td data-v-6af299b3>No / Yes</td><td data-v-6af299b3><span class="badge pd" data-v-6af299b3>PD</span></td></tr><tr data-v-6af299b3><td data-v-6af299b3>Any</td><td data-v-6af299b3>PD</td><td data-v-6af299b3>No / Yes</td><td data-v-6af299b3><span class="badge pd" data-v-6af299b3>PD</span></td></tr><tr data-v-6af299b3><td data-v-6af299b3>Any</td><td data-v-6af299b3>Any</td><td data-v-6af299b3>Yes</td><td data-v-6af299b3><span class="badge pd" data-v-6af299b3>PD</span> ← 最高优先级</td></tr></tbody></table></div></div><div class="section concepts-section" data-v-6af299b3><h3 class="section-title" data-v-6af299b3>关键概念</h3><div class="concept-grid" data-v-6af299b3><div class="concept-card" data-v-6af299b3><h4 data-v-6af299b3>SLD（最长径之和）</h4><p data-v-6af299b3>Sum of Longest Diameters —— 所有靶病灶最长直径之和。每次访视计算一次，用于与基线和历史最低值比较。</p></div><div class="concept-card" data-v-6af299b3><h4 data-v-6af299b3>Nadir（研究期间最低值）</h4><p data-v-6af299b3>SLD_nadir = min(基线, 第1次随访, 第2次随访, ...)。PD 判定的参照基准是 <strong data-v-6af299b3>nadir 不是基线</strong>。</p></div><div class="concept-card" data-v-6af299b3><h4 data-v-6af299b3>明确进展（Unequivocal）</h4><p data-v-6af299b3>仅用于非靶病灶 PD 判定。要求&quot;明确&quot;的客观进展证据（如胸水明显增多），轻微尺寸变化不构成 PD。</p></div><div class="concept-card" data-v-6af299b3><h4 data-v-6af299b3>新病灶（New Lesion）</h4><p data-v-6af299b3>治疗过程中新出现的任何病灶，无论大小、位置、发现方式（含 FDG-PET）。一旦确认即判为 PD（最高优先级一票否决）。</p></div></div></div></div>',2)])]))}},n=t(b,[["__scopeId","data-v-6af299b3"]]);export{n as default};
